const e=[{id:1,picture:new URL("/assets/dinosaur.b90a4df3.jpeg",self.location).href,date:2026,description:"This photo is a joke from Vincent. And it is the only picture that is made by Ai here. All other photos are real. Vincent created this photo in 2026 in July"},{id:2,picture:new URL("/assets/Screenshot2026fifa.e570d25f.png",self.location).href,date:2026,description:"Spainish team are the champions of 2026 FIFA (Federation International Football Association) cup. And Donald Trump was asked to leave the photo but he rejected and stayed in the photo"},{id:3,picture:new URL("/assets/uranus.fc4e37eb.jpg",self.location).href,date:2020,description:"Who knew? When teacher Vincent wrote this on the board he didn`t know what was gonna happen in 2022... But there is one more funny thing in this photo: Can you show me Uranus? ;)"},{id:4,picture:new URL("/assets/uazLegend.47c4a51f.jpg",self.location).href,date:1958,description:"Some things in life need evolution to become perfect. But the God created Perfect Ideal car right from his first attempt. \u0411\u0443\u0445\u0430\u043D\u043A\u0443 \u0411\u043E\u0433 \u0441\u0440\u0430\u0437\u0443 \u0441\u043E\u0437\u0434\u0430\u043B \u0438\u0434\u0435\u0430\u043B\u044C\u043D\u043E\u0439! \u0421 \u043F\u0435\u0440\u0432\u043E\u0439 \u043F\u043E\u043F\u044B\u0442\u043A\u0438"},{id:5,picture:new URL("/assets/endOfWorldWar2 1945 august 14.1752303e.png",self.location).href,date:1945,description:"People are celebrating at Times Square New York. When World War II ended on August 14th, 1945 the mood on the streets of New York was euphoric."},{id:6,picture:new URL("/assets/MarilynMonroe1957.c656a292.png",self.location).href,date:1957,description:"This photo was taken by Richard Avedon. And in this pic you see Marilyn Monroe, New York, May 6, 1957"},{id:7,picture:new URL("/assets/muhammadAli1965.debf3309.png",self.location).href,date:1965,description:"Muhammad Ali vs. Sonny Liston \u2013 It was only one minute and 44 seconds into the first round that Ali dealt a winning knockout blow to Liston\u2019s head."},{id:8,picture:new URL("/assets/lunchNewYork1932.2e3c1116.png",self.location).href,date:1932,description:"It\u2019s hard to believe that this photo is real. But it is real and it is legendary! 11 construction workers on their lunch break. They are eating, chatting and smoking on a steel beam 200 (two hundred) metres above Manhattan. The 69th floor of the Rockerfeller Centre"},{id:9,picture:new URL("/assets/brezhnevKiss.9c5610c6.jpg",self.location).href,date:1979,description:'The famous "Brotherly Kiss" photo. Here you can see Leonid Brezhnev \u2014 the Soviet Union leader who was known for the "Era of Stagnation". And another man is Erich Honecker \u2014 the leader of East Germany. In this photo we see so-called "socialist brotherly kiss" \u2014 a traditional greeting between leaders of socialist countries, symbolizing trust, friendship, and solidarity. \u0412 \u0442\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u0430 \u044D\u0442\u043E \u0431\u044B\u043B\u043E \u0442\u0440\u0430\u0434\u0438\u0446\u0438\u043E\u043D\u043D\u043E\u0435 \u043F\u0430\u0440\u0442\u0438\u0439\u043D\u043E\u0435 \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435, \u0441\u0438\u043C\u0432\u043E\u043B\u0438\u0437\u0438\u0440\u0443\u044E\u0449\u0435\u0435 \u0432\u044B\u0441\u0448\u0443\u044E \u0441\u0442\u0435\u043F\u0435\u043D\u044C \u0434\u043E\u0432\u0435\u0440\u0438\u044F, \u0434\u0440\u0443\u0436\u0431\u044B \u0438 \u0441\u043E\u043B\u0438\u0434\u0430\u0440\u043D\u043E\u0441\u0442\u0438 \u043C\u0435\u0436\u0434\u0443 \u043B\u0438\u0434\u0435\u0440\u0430\u043C\u0438 \u0441\u043E\u0446\u0438\u0430\u043B\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u0441\u0442\u0440\u0430\u043D.'},{id:10,picture:new URL("/assets/nineEleven.a0896ab4.jpg",self.location).href,date:2001,description:"One of the most recognizable images from the deadliest terrorist attack in U.S. history. On the eleventh of September in 2001. Two hijacked planes flew into the North and South towers of World Trade Center. It caused both Twin Towers 110-story skyscrapers to collapse within hours. Nearly 3,000 people lost their lives that day. The attacks reshaped global politics and changed airport security forever."},{id:11,picture:new URL("/assets/nagasaki.cd50eef6.jpg",self.location).href,date:1945,description:'"Nagasaki Mushroom Cloud" - This image catches the atomic bomb explosion over Nagasaki, Japan, just three days after Hiroshima. The blast killed an estimated 40,000 people (forty thousand) instantly, with tens of thousands more dying from radiation exposure in the following months. It is still one of the most powerful and haunting images of the nuclear age.'},{id:12,picture:new URL("/assets/blackWhite.155a5f2d.jpg",self.location).href,date:1950,description:'The photo shows a black man drinking from a "Colored" water fountain in the American South, during the era of racial segregation. It became a powerful symbol of the Civil Rights Movement and the fight against racial inequality in the United States.'},{id:13,picture:new URL("/assets/kiss_of_life.20c6f01e.png",self.location).href,date:1967,description:'Pulitzer Prize-winning photo. "Kiss of Life" was taken in 1967. It shows electrician J.D. Thompson performing mouth-to-mouth resuscitation on his unconscious colleague Randall Champion, who had been electrocuted by a 4,160-volt line while hanging upside down on a utility pole. Champion survived and lived until 2002. An iconic symbol of heroism in American history.'},{id:14,picture:new URL("/assets/einstein.78c0b4f9.jpg",self.location).href,date:1951,description:"Albert Einstein is showing his tongue on his 72nd birthday. It was in March, on the  14th of the year 1951. A photographer asked him to smile for the camera. Instead of a polite smile, Einstein playfully showed his tongue \u2014 and the image became one of the most pics in the world. It captures the brilliant physicist's sense of humor and his refusal to take himself too seriously."},{id:15,picture:new URL("/assets/victory.e1b2e645.jpg",self.location).href,date:1945,description:"This photo was staged. But anyways it is one of the most famous photos! May 1945. It shows Soviet soldiers raising the red flag over the Reichstag in Berlin, symbolizing the end of World War II."},{id:16,picture:new URL("/assets/beast.0aae24ec.jpg",self.location).href,date:1934,description:'The famous "Loch Ness Monster" photo, taken in 1934 by London doctor Kenneth Wilson. He later admitted it was a fake \u2014 he had made it for fun. But it was too late. The image sparked a global obsession that lasted for decades. It was proven fake in 1994, yet even today, many still believe in Loch Ness Monster. A perfect example of how a simple joke can become a legend.'},{id:17,picture:new URL("/assets/bjenksi3.9e64ed7e.jpg",self.location).href,date:2010,description:"This graffiti was painted in May 2010 on the back of one restaurant in Boston's Chinatown. The artwork shows a sad poor man, whose dreams are cancelled. It became a symbol of broken hopes and economic struggles."},{id:18,picture:new URL("/assets/Screenshot.375eaa6b.png",self.location).href,date:2018,description:`Banksy's "Girl with Balloon" \u2014 a graffiti of a girl reaching for a heart-shaped balloon, first appeared in London in 2002. In 2018, a framed copy sold at Sotheby's for \xA31,042,000 \u2014 and then self-destructed. A hidden shredder Banksy had built into the frame activated right after the hammer fell, partially destroying the artwork. It was renamed "Love is in the Bin". In 2021, the shredded piece sold again for a record-breaking \xA318 million.`},{id:19,picture:new URL("/assets/agents_TJPEG.30039d62.jpeg",self.location).href,date:2023,description:"Maybe it was in 2024... Vincent has a fish memory))) He doesn`t remember exactly. But in this picture you see special agents AKA students who helped their teacher during a photo-shoot (\u0444\u043E\u0442\u043E\u0441\u0435\u0441\u0441\u0438\u044F) Russel, Synthia, Shally, Tyler - HUGE THANKS TO YOU! Appreciate it."},{id:20,picture:new URL("/assets/ShallyPhoto.46e8f682.jpeg",self.location).href,date:2018,description:"The Golden Bridge in Vietnam was built in 2018. The architector wanted to show a beautiful view from God's hands. As a result this creation attracted many tourists from all over the world to Vietnam. Do you want to visit this place?"},{id:21,picture:new URL("/assets/June.4c4a2beb.png",self.location).href,date:2025,description:"We tried to sup-board down the river in Big Goloustnoe (Baikal Lake region) but we stuck on the rocks because the river was not deep enough. Shallow - \u043C\u0435\u043B\u043A\u043E - \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u0433\u043B\u0443\u0431\u043E\u043A\u043E, \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u043D\u043E"},{id:22,picture:new URL("/assets/May.b8dfe3f8.png",self.location).href,date:2025,description:"It was the first time when Vincent was in the St.P. metro. We went to celebrate my nephew`s 25th anniversary. He is 25 in the year 2025, sounds cool, right? "},{id:23,picture:new URL("/assets/Nov.ae3fb1f6.png",self.location).href,date:2024,description:"Sweet November and Phoebe is baking buns"},{id:24,picture:new URL("/assets/linoleumTJPG.830df01e.jpg",self.location).href,date:2026,description:"Vincent ordered 50 squared metres of Linoleum. But the length was 4 metres! It was impossible to bring it up to the 4th floor in a very narrow hallway. So, Vincent had an idea to cut the pieces of linoleum on a parking lot. All neighbours were watching and smiling."},{id:50,picture:new URL("/assets/Oct.5763b986.png",self.location).href,date:2024,description:"Catober = Cat + october. This is the first photo that Vincent uploaded to this App when he was creating it. It is Polina and Cassey."},{id:51,picture:new URL("/assets/Febr.ae9300df.png",self.location).href,date:2025,description:"Fur Fur Fur February in Siberia! Vincent`s wife Polina is showing off with her new furcoat. Pretty and playful as always"}],t=()=>[...e];export{t as g};
